        complexity: "Time: O(n² · k) | Space: O(n · k)",
        language: "javascript",
        code: "function solve(num, k) {\n  const n = num.length;\n  if (k >= n) return \"0\";\n  if (k <= 0) {\n    const only = num.replace(/^0+/, \"\");\n    return only === \"\" ? \"0\" : only;\n  }\n  let dp = new Array(k + 1).fill(null);\n  dp[0] = \"\";\n  for (let i = 1; i <= n; i++) {\n    const nxt = new Array(k + 1).fill(null);\n    for (let j = 0; j <= k; j++) {\n      let best = null;\n      if (dp[j] !== null) best = dp[j] + num[i - 1];\n      if (j > 0 && dp[j - 1] !== null) {\n        const cand = dp[j - 1];\n        if (best === null || cand < best) best = cand;\n      }\n      nxt[j] = best;\n    }\n    dp = nxt;\n  }\n  const res = (dp[k] === null ? \"\" : dp[k]).replace(/^0+/, \"\");\n  return res === \"\" ? \"0\" : res;\n}",
