        title: "Brute Force",
        complexity: "Time: O(n^2) | Space: O(n)",
        language: "javascript",
        code: "function solve(s) {\n  const t = s.split(' ').join('');\n  let depth = 0;\n  let prev = 'start';\n  for (const c of t) {\n    if (c >= '0' && c <= '9') {\n      if (prev === 'close') return -1;\n      prev = 'num';\n    } else if (c === '+' || c === '-') {\n      if (prev !== 'num' && prev !== 'close') return -1;\n      prev = 'op';\n    } else if (c === '(') {\n      if (prev !== 'start' && prev !== 'op' && prev !== 'open') return -1;\n      depth++;\n      prev = 'open';\n    } else if (c === ')') {\n      if (prev !== 'num' && prev !== 'close') return -1;\n      depth--;\n      if (depth < 0) return -1;\n      prev = 'close';\n    } else {\n      return -1;\n    }\n  }\n  if (prev !== 'num' && prev !== 'close') return -1;\n  if (depth !== 0) return -1;\n\n  const MOD = 1000000007;\n  const norm = (x) => ((x % MOD) + MOD) % MOD;\n\n  const evaluate = (part) => {\n    let res = 0;\n    let sign = 1;\n    let num = 0;\n    let i = 0;\n    while (i < part.length) {\n      const c = part[i];\n      if (c >= '0' && c <= '9') {\n        num = (num * 10 + (c.charCodeAt(0) - 48)) % MOD;\n        i++;\n      } else if (c === '+' || c === '-') {\n        res = norm(res + sign * num);\n        num = 0;\n        sign = c === '+' ? 1 : -1;\n        i++;\n      } else {\n        let d = 0;\n        let j = i;\n        while (j < part.length) {\n          if (part[j] === '(') d++;\n          else if (part[j] === ')') {\n            d--;\n            if (d === 0) break;\n          }\n          j++;\n        }\n        res = norm(res + sign * num);\n        num = 0;\n        res = norm(res + sign * evaluate(part.slice(i + 1, j)));\n        sign = 1;\n        i = j + 1;\n      }\n    }\n    return norm(res + sign * num);\n  };\n\n  return evaluate(t);\n}",
