        title: "Brute Force",
        complexity: "Time: O(n^2) | Space: O(n)",
        language: "javascript",
        code: "function solve(s) {\n  const src = s.replace(/\\s+/g, '');\n  let i = 0, depth = 0, need = true, ok = true;\n  while (i < src.length) {\n    const c = src[i];\n    if (c >= '0' && c <= '9') {\n      if (!need) { ok = false; break; }\n      while (i < src.length && src[i] >= '0' && src[i] <= '9') i++;\n      need = false;\n    } else if (c === '(') {\n      if (!need) { ok = false; break; }\n      depth++; i++;\n    } else if (c === ')') {\n      if (need || depth === 0) { ok = false; break; }\n      depth--; i++;\n    } else if (c === '+' || c === '-' || c === '*' || c === '/') {\n      if (need) { ok = false; break; }\n      need = true; i++;\n    } else { ok = false; break; }\n  }\n  if (!ok || need || depth !== 0) return \"0\";\n\n  function calc(a, op, b) {\n    if (op === '+') return a + b;\n    if (op === '-') return a - b;\n    if (op === '*') return a * b;\n    if (b === 0n) return 0n;\n    return a / b;\n  }\n\n  function ev(t) {\n    let d = 0, split = -1;\n    for (let k = t.length - 1; k >= 0; k--) {\n      const c = t[k];\n      if (c === ')') d++;\n      else if (c === '(') d--;\n      else if (d === 0 && (c === '+' || c === '-')) { split = k; break; }\n    }\n    if (split === -1) {\n      d = 0;\n      for (let k = t.length - 1; k >= 0; k--) {\n        const c = t[k];\n        if (c === ')') d++;\n        else if (c === '(') d--;\n        else if (d === 0 && (c === '*' || c === '/')) { split = k; break; }\n      }\n    }\n    if (split !== -1) {\n      const left = ev(t.slice(0, split));\n      const right = ev(t.slice(split + 1));\n      return calc(left, t[split], right);\n    }\n    if (t[0] === '(') return ev(t.slice(1, -1));\n    return BigInt(t);\n  }\n\n  return ev(src).toString();\n}",
