        code: "function mergeKLists(lists) {\n  const all = [];\n  for (let i = 0; i < lists.length; i++) {\n    for (let j = 0; j < lists[i].length; j++) {\n      all.push(lists[i][j]);\n    }\n  }\n  all.sort((a, b) => a - b);\n  return all;\n}",
