        language: "javascript",
        code: "function lastStoneWeight(stones) {\n  let piles = stones.slice();\n  while (piles.length > 1) {\n    piles.sort((a, b) => a - b);\n    const y = piles.pop();\n    const x = piles.pop();\n    if (y !== x) piles.push(y - x);\n  }\n  return piles.length === 0 ? 0 : piles[0];\n}",
