        code: "function lastStoneWeight(stones) {\n  const heap = [];\n  function push(v) {\n    heap.push(v);\n    let i = heap.length - 1;\n    while (i > 0) {\n      const p = (i - 1) >> 1;\n      if (heap[p] >= heap[i]) break;\n      const t = heap[p];\n      heap[p] = heap[i];\n      heap[i] = t;\n      i = p;\n    }\n  }\n  function pop() {\n    const top = heap[0];\n    const last = heap.pop();\n    if (heap.length > 0) {\n      heap[0] = last;\n      let i = 0;\n      while (true) {\n        const l = 2 * i + 1;\n        const r = 2 * i + 2;\n        let s = i;\n        if (l < heap.length && heap[l] > heap[s]) s = l;\n        if (r < heap.length && heap[r] > heap[s]) s = r;\n        if (s === i) break;\n        const t = heap[s];\n        heap[s] = heap[i];\n        heap[i] = t;\n        i = s;\n      }\n    }\n    return top;\n  }\n  for (const s of stones) push(s);\n  while (heap.length > 1) {\n    const y = pop();\n    const x = pop();\n    if (y !== x) push(y - x);\n  }\n  return heap.length === 0 ? 0 : heap[0];\n}",
