        code: "function solve(grid) {\n  const rows = grid.length;\n  const cols = grid[0].length;\n  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n  const inA = Array.from({ length: rows }, () => new Array(cols).fill(false));\n  let si = -1;\n  let sj = -1;\n  for (let i = 0; i < rows && si === -1; i++) {\n    for (let j = 0; j < cols; j++) {\n      if (grid[i][j] === 1) {\n        si = i;\n        sj = j;\n        break;\n      }\n    }\n  }\n  if (si === -1) return -1;\n  const stack = [[si, sj]];\n  inA[si][sj] = true;\n  while (stack.length > 0) {\n    const cell = stack.pop();\n    for (const d of dirs) {\n      const x = cell[0] + d[0];\n      const y = cell[1] + d[1];\n      if (x >= 0 && y >= 0 && x < rows && y < cols && grid[x][y] === 1 && !inA[x][y]) {\n        inA[x][y] = true;\n        stack.push([x, y]);\n      }\n    }\n  }\n  let best = Infinity;\n  for (let i = 0; i < rows; i++) {\n    for (let j = 0; j < cols; j++) {\n      if (!inA[i][j]) continue;\n      const dist = Array.from({ length: rows }, () => new Array(cols).fill(-1));\n      dist[i][j] = 0;\n      const queue = [[i, j]];\n      let head = 0;\n      while (head < queue.length) {\n        const cell = queue[head];\n        head++;\n        if (!inA[cell[0]][cell[1]] && grid[cell[0]][cell[1]] === 1) {\n          if (dist[cell[0]][cell[1]] - 1 < best) best = dist[cell[0]][cell[1]] - 1;\n          break;\n        }\n        for (const d of dirs) {\n          const x = cell[0] + d[0];\n          const y = cell[1] + d[1];\n          if (x >= 0 && y >= 0 && x < rows && y < cols && dist[x][y] === -1) {\n            dist[x][y] = dist[cell[0]][cell[1]] + 1;\n            queue.push([x, y]);\n          }\n        }\n      }\n    }\n  }\n  return best === Infinity ? -1 : best;\n}",
