        title: "Brute Force",
        complexity: "Time: O(E!) | Space: O(E)",
        language: "javascript",
        code: "function solve(edges) {\n  const e = Math.floor(edges.length / 2);\n  if (e === 0) return [0];\n  const order = [];\n  for (let i = 0; i < e; i++) order.push(i);\n  order.sort((a, b) => {\n    if (edges[2 * a] !== edges[2 * b]) return edges[2 * a] - edges[2 * b];\n    if (edges[2 * a + 1] !== edges[2 * b + 1]) return edges[2 * a + 1] - edges[2 * b + 1];\n    return a - b;\n  });\n  const used = new Array(e).fill(false);\n  const path = [0];\n  function search(node, count) {\n    if (count === e) return true;\n    for (let t = 0; t < e; t++) {\n      const t2 = order[t];\n      if (used[t2]) continue;\n      if (edges[2 * t2] !== node) continue;\n      used[t2] = true;\n      path.push(edges[2 * t2 + 1]);\n      if (search(edges[2 * t2 + 1], count + 1)) return true;\n      path.pop();\n      used[t2] = false;\n    }\n    return false;\n  }\n  if (search(0, 0)) return path;\n  return [];\n}",
