        code: "function solve(edges) {\n  const e = Math.floor(edges.length / 2);\n  if (e === 0) return [0];\n  const adj = new Map();\n  for (let t = 0; t < e; t++) {\n    const u = edges[2 * t];\n    if (!adj.has(u)) adj.set(u, []);\n    adj.get(u).push(edges[2 * t + 1]);\n  }\n  adj.forEach((list) => list.sort((a, b) => a - b));\n  const stack = [0];\n  const out = [];\n  while (stack.length > 0) {\n    const u = stack[stack.length - 1];\n    const list = adj.get(u);\n    if (list !== undefined && list.length > 0) {\n      stack.push(list.shift());\n    } else {\n      out.push(stack.pop());\n    }\n  }\n  if (out.length !== e + 1) return [];\n  out.reverse();\n  const need = new Map();\n  for (let t = 0; t < e; t++) {\n    const key = edges[2 * t] + \",\" + edges[2 * t + 1];\n    need.set(key, (need.get(key) || 0) + 1);\n  }\n  for (let i = 0; i + 1 < out.length; i++) {\n    const key = out[i] + \",\" + out[i + 1];\n    const left = need.get(key);\n    if (left === undefined || left === 0) return [];\n    need.set(key, left - 1);\n  }\n  return out;\n}",
