        code: "function solve(num) {\n  if (num <= 0) return \"\";\n  const places = [\n    [\"\", \"M\", \"MM\", \"MMM\"],\n    [\"\", \"C\", \"CC\", \"CCC\", \"CD\", \"D\", \"DC\", \"DCC\", \"DCCC\", \"CM\"],\n    [\"\", \"X\", \"XX\", \"XXX\", \"XL\", \"L\", \"LX\", \"LXX\", \"LXXX\", \"XC\"],\n    [\"\", \"I\", \"II\", \"III\", \"IV\", \"V\", \"VI\", \"VII\", \"VIII\", \"IX\"],\n  ];\n  const digits = String(num).split(\"\").map(Number);\n  let out = \"\";\n  for (let i = 0; i < digits.length; i++) {\n    const place = 4 - digits.length + i;\n    if (place < 0) continue;\n    const glyph = places[place][digits[i]];\n    if (glyph) out += glyph;\n  }\n  return out;\n}",
