        code: "function solve(s) {\n  const cnt = new Array(26).fill(0);\n  for (const ch of s) cnt[ch.charCodeAt(0) - 97] += 1;\n  const n = s.length;\n  let peak0 = 0;\n  for (const c of cnt) if (c > peak0) peak0 = c;\n  if (peak0 > Math.ceil(n / 2)) return \"\";\n  const memo = new Map();\n  function go(counts, prev) {\n    let total = 0;\n    for (const c of counts) total += c;\n    if (total === 0) return \"\";\n    const key = counts.join(\",\") + \"|\" + prev;\n    if (memo.has(key)) return memo.get(key);\n    let best = null;\n    for (let c = 0; c < 26; c++) {\n      if (counts[c] === 0 || c === prev) continue;\n      counts[c] -= 1;\n      const rest = go(counts, c);\n      counts[c] += 1;\n      if (rest !== null) {\n        const cand = String.fromCharCode(97 + c) + rest;\n        if (best === null || cand < best) best = cand;\n      }\n    }\n    memo.set(key, best);\n    return best;\n  }\n  const res = go(cnt, -1);\n  return res === null ? \"\" : res;\n}",
