        language: "javascript",
        code: "function solve(s) {\n  const n = s.length;\n  const dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(false));\n  for (let i = 0; i <= n; i++) dp[i][i] = true;\n  for (let len = 1; len <= n; len++) {\n    for (let i = 0; i + len <= n; i++) {\n      const j = i + len;\n      let ok = false;\n      if (s[i] === '*' && dp[i + 1][j]) ok = true;\n      if (!ok && (s[i] === '(' || s[i] === '*')) {\n        for (let k = i + 2; k <= j; k++) {\n          const closer = s[k - 1];\n          if ((closer === ')' || closer === '*') && dp[i + 1][k - 1] && dp[k][j]) {\n            ok = true;\n            break;\n          }\n        }\n      }\n      dp[i][j] = ok;\n    }\n  }\n  return dp[0][n];\n}",
