        complexity: "Time: O(1) (at most 81 pruned placements) | Space: O(1) extra",
        language: "javascript",
        code: "function solve(s) {\n  const n = s.length;\n  const out = [];\n  const parts = [];\n  function dfs(start) {\n    if (parts.length === 4) {\n      if (start === n) out.push(parts.join(\".\"));\n      return;\n    }\n    for (let len = 1; len <= 3; len++) {\n      if (start + len > n) break;\n      const seg = s.slice(start, start + len);\n      if (seg.length > 1 && seg[0] === \"0\") break;\n      if (Number(seg) > 255) break;\n      parts.push(seg);\n      dfs(start + len);\n      parts.pop();\n    }\n  }\n  dfs(0);\n  out.sort();\n  return out;\n}",
