        code: "function solve(matrix) {\n  const m = matrix.length;\n  const n = matrix[0].length;\n  const rowZero = new Array(m).fill(false);\n  const colZero = new Array(n).fill(false);\n  for (let i = 0; i < m; i++) {\n    for (let j = 0; j < n; j++) {\n      if (matrix[i][j] === 0) {\n        rowZero[i] = true;\n        colZero[j] = true;\n      }\n    }\n  }\n  const res = matrix.map((row) => row.slice());\n  for (let i = 0; i < m; i++) {\n    for (let j = 0; j < n; j++) {\n      if (rowZero[i] || colZero[j]) res[i][j] = 0;\n    }\n  }\n  return res;\n}",
