        code: "function solve(num) {\n  if (num === 0) return 'Zero';\n  const small = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven',\n    'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen',\n    'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];\n  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty',\n    'Seventy', 'Eighty', 'Ninety'];\n  const scales = ['', 'Thousand', 'Million', 'Billion'];\n  function chunkToWords(value) {\n    const parts = [];\n    let rest = value;\n    if (rest >= 100) {\n      parts.push(small[Math.floor(rest / 100)]);\n      parts.push('Hundred');\n      rest = rest % 100;\n    }\n    if (rest >= 20) {\n      parts.push(tens[Math.floor(rest / 10)]);\n      rest = rest % 10;\n    }\n    if (rest > 0) parts.push(small[rest]);\n    return parts.join(' ');\n  }\n  const groups = [];\n  let value = num;\n  let index = 0;\n  while (value > 0) {\n    const chunk = value % 1000;\n    if (chunk > 0) {\n      const words = chunkToWords(chunk);\n      groups.unshift(index > 0 ? words + ' ' + scales[index] : words);\n    }\n    value = Math.floor(value / 1000);\n    index++;\n  }\n  return groups.join(' ');\n}",
